		private static void Register(string text, int type)
		{
			var hash = Hash(text.AsSpan());
			var index = (int)(hash & (Size - 1));
			while(_keys[index] != null) {
				if(_hashes[index] == hash && _keys[index] == text) { return; }  // 重复定义，保留先注册的
				index = (index + 1) & (Size - 1);
			}
			_hashes[index] = hash;
			_keys[index] = text;
			_types[index] = type;
		}

		/// <summary>
		/// 计算文本哈希。逐字符按 CharUtil 归一化(大小写、全角、中文等)后再取哈希，
		/// 保证 "<c>error</c>" / "<c>ＥＲＲＯＲ</c>" 与注册的 "<c>ERROR</c>" 得到同一哈希。
		/// </summary>
		internal static ulong Hash(ReadOnlySpan<char> text)
		{
			ulong hash = 14695981039346656037UL;
			for(int i = 0; i < text.Length; i++) {
				hash ^= CharUtilStandard(text[i]);
				hash *= 1099511628211UL;
			}
			return hash;
		}

		/// <summary>
		/// 按哈希查找 Token 类型，未找到返回 0
		/// </summary>
		internal static int Find(ulong hash, ReadOnlySpan<char> text)
		{
			var index = (int)(hash & (Size - 1));
			while(true) {
				var key = _keys[index];
				if(key == null) { return 0; }
				if(_hashes[index] == hash && EqualsStandard(text, key.AsSpan())) { return _types[index]; }
				index = (index + 1) & (Size - 1);
			}
		}

		/// <summary>
		/// 与 CharUtil 等价的大小写/全角不敏感比较
		/// </summary>
		private static bool EqualsStandard(ReadOnlySpan<char> left, ReadOnlySpan<char> right)
		{
			if(left.Length != right.Length) { return false; }
			for(int i = 0; i < left.Length; i++) {
				var l = left[i];
				var r = right[i];
				if(l == r) { continue; }
				if(CharUtilStandard(l) != CharUtilStandard(r)) { return false; }
			}
			return true;
		}

